bool isNotPrime[1000000]; // Array to mark non-prime numbers

int main(void)

{

	long long i,j,sqrtOfN,n,count; // Declare variables

	sqrtOfN = (long long)sqrt(1000000.0); // Calculate square root

	for(i = 3; i <= sqrtOfN; i = i + 2) // Loop through odd numbers

	{

		if(isNotPrime[i] == false) // Check if prime

		{

			for(j = i * i; j <= 1000000; j = j + 2 * i) // Mark multiples of i

			{

				isNotPrime[j] = true; // Mark as non-prime

			}

		}

	}



	while((scanf("%lld",&n)) != EOF) // Input for n

	{

		if(n == 1 || n == 0) // Edge cases

			count = 0;

		else

		{

			count = 1;

			for(i = 3; i <= n; i = i + 2) // Count primes

			{

				if(isNotPrime[i] == false)

					count++;

			}

		}

		printf("%lld\n",count); // Output count

	}

	return 0;

}

